*, *::before, *::after {
  box-sizing: border-box;   /* width now includes padding and border */
}

.card {
  width: 300px;             /* the whole box is exactly 300px wide */
  padding: 1rem;            /* 16px at the default font size */
  border: 2px solid #ccc;
  margin: 0 auto 2rem;      /* top 0, sides auto (centered), bottom 2rem */
}

/* from the outside in: margin > border > padding > content */

.navbar {
  display: flex;
  align-items: center;                 /* vertically centered in the row */
  gap: 1rem;
}
.navbar .logo { margin-right: auto; }  /* pushes the links to the right */

.layout  { display: flex; }
.sidebar { width: 250px; }
.content { flex: 1; }                  /* takes all the remaining width */

.tags { display: flex; flex-wrap: wrap; gap: 8px; }

.gallery {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1rem;
}

.page {
  display: grid;
  grid-template-columns: 220px 1fr;
  grid-template-areas:
    "header  header"
    "sidebar main"
    "footer  footer";
  gap: 1rem;
}
.page > header { grid-area: header; }
.page > aside  { grid-area: sidebar; }
.page > main   { grid-area: main; }
.page > footer { grid-area: footer; }

:root {
  --bg: #ffffff;
  --text: #1a1a1a;
  --brand: #0b6bcb;
  --space: 1rem;
}
@media (prefers-color-scheme: dark) {
  :root { --bg: #121212; --text: #eeeeee; --brand: #6aa9ff; }
}

body    { background: var(--bg); color: var(--text); }
.button { background: var(--brand); padding: calc(var(--space) / 2) var(--space); }

/* mobile first: one column, then two from 768px up */
.layout { display: grid; gap: var(--space); }
@media (min-width: 768px) {
  .layout { grid-template-columns: 250px 1fr; }
}
img { max-width: 100%; height: auto; }

